using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using System.Text.Json.Nodes;
using WinUIEx;
namespace ClipWeave;
sealed class SettingsWindow:Window {
    readonly MainWindow owner;readonly TabView tabs=new(){IsAddTabButtonVisible=false};
    readonly TextBlock notice=Palette.Text("");readonly Grid root=new(){Background=Palette.White};
    bool busy;
    JsonObject Config=>owner.Status["config"] as JsonObject??new();
    public SettingsWindow(MainWindow owner){this.owner=owner;Title=L10n.Text("设置")+" — Clipper";root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.Children.Add(tabs);notice.Margin=new Thickness(24,8,24,16);Grid.SetRow(notice,1);root.Children.Add(notice);Content=root;AppWindow.Resize(new Windows.Graphics.SizeInt32(880,710));this.CenterOnScreen();Closed+=(_,_)=>owner.SettingsClosed();Build();}
    StackPanel Page(string heading,string detail=""){var p=new StackPanel{Spacing=20,Margin=new Thickness(30),MaxWidth=720,HorizontalAlignment=HorizontalAlignment.Stretch};p.Children.Add(Palette.Text(L10n.Text(heading),24,true));if(detail.Length>0)p.Children.Add(Palette.Text(L10n.Text(detail)));return p;}
    void Tab(string title,StackPanel page){tabs.TabItems.Add(new TabViewItem{Header=L10n.Text(title),IsClosable=false,Content=new ScrollViewer{Content=page,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}});}
    Button Button(string title,Func<Task> action){var b=new Button{Content=L10n.Text(title)};b.Click+=async(_,_)=>await Run(action);return b;}
    async Task Run(Func<Task> action){if(busy)return;busy=true;tabs.IsEnabled=false;notice.Text="";try{await action();notice.Text=L10n.Text("已更新");}catch(Exception e){notice.Text=L10n.Text(e.Message);}finally{busy=false;tabs.IsEnabled=true;}}
    void Toggle(StackPanel p,string title,bool value,Func<bool,Task> save){var toggle=new ToggleSwitch{Header=L10n.Text(title),IsOn=value};toggle.Toggled+=async(_,_)=>await Run(async()=>{try{await save(toggle.IsOn);}catch{toggle.IsOn=!toggle.IsOn;throw;}});p.Children.Add(toggle);}
    void Setting(StackPanel p,string label,string key)=>Toggle(p,label,Config[key]?.GetValue<bool>()==true,on=>owner.SaveConfig(new(){[key]=on}));
    void Build(){
        var general=Page("通用");Toggle(general,"固定面板",owner.Preferences.Pinned,on=>{owner.Preferences.Pinned=on;owner.Preferences.Save();return Task.CompletedTask;});
        Toggle(general,"显示托盘图标",owner.Preferences.ShowTray,on=>{if(!on&&!owner.Shell.HotkeyAvailable)throw new IOException(L10n.Text("快捷键已被占用，请保留托盘图标。"));owner.Preferences.ShowTray=on;owner.Preferences.Save();owner.Shell.SetTrayVisible(on);return Task.CompletedTask;});
        general.Children.Add(Palette.Text("Ctrl + Shift + V · "+L10n.Text(owner.Shell.HotkeyAvailable?"显示或隐藏面板":"快捷键已被占用，请使用托盘菜单")));
        Setting(general,"自动记录剪贴板","captureEnabled");Setting(general,"记录文件与文件夹","captureFiles");Setting(general,"复制后直接粘贴","directPaste");
        var excluded=new TextBox{Header=L10n.Text("排除的应用（进程名，每行一个）"),AcceptsReturn=true,Height=80,Text=Config["excludedApps"]?.ToString()??""};general.Children.Add(excluded);general.Children.Add(Button("保存排除应用",()=>owner.SaveConfig(new(){["excludedApps"]=excluded.Text})));
        var retention=new ComboBox{Header=L10n.Text("历史保留期限"),HorizontalAlignment=HorizontalAlignment.Stretch};int[] days=[0,7,30,90];foreach(var d in days)retention.Items.Add(d==0?L10n.Text("永久保留"):d+" "+L10n.Text("天"));retention.SelectedIndex=Math.Max(0,Array.IndexOf(days,Config["retentionDays"]?.GetValue<int>()??0));general.Children.Add(retention);general.Children.Add(Button("保存保留期限",async()=>{var d=days[Math.Max(0,retention.SelectedIndex)];if(d>0&&await owner.Dialog(L10n.Text("更改保留期限"),Palette.Text(L10n.Text("超过期限的记录将被删除，并同步到其他设备。")),L10n.Text("确认"))!=ContentDialogResult.Primary)return;await owner.SaveConfig(new(){["retentionDays"]=d});}));Tab("通用",general);
        var account=Page("账户与设备");account.Children.Add(Palette.Text(Config["email"]?.ToString()??"" ,18,true));account.Children.Add(Palette.Text("api.cliper.dev"));account.Children.Add(Button("立即同步",()=>owner.SyncNow()));account.Children.Add(Button("已连接的设备",()=>owner.ShowDevices()));
        var events=new TextBlock{TextWrapping=TextWrapping.Wrap,IsTextSelectionEnabled=true};account.Children.Add(Button("查看安全事件",async()=>{var data=await owner.CallCore("events");var list=data as JsonArray??(data as JsonObject)?["events"] as JsonArray??new();events.Text=string.Join("\n\n",list.OfType<JsonObject>().TakeLast(12).Select(e=>string.Join(" · ",new[]{e["type"]?.ToString()??e["action"]?.ToString()??e["event"]?.ToString()??"",e["created"]?.ToString()??e["createdAt"]?.ToString()??"",e["deviceName"]?.ToString()??""}.Where(x=>x.Length>0))));}));account.Children.Add(events);
        account.Children.Add(Button("断开账户连接",async()=>{if(await owner.Dialog(L10n.Text("断开账户连接"),Palette.Text(L10n.Text("本机将停止云端同步，请先保存恢复文件。")),L10n.Text("断开连接"))!=ContentDialogResult.Primary)return;await owner.CallCore("disconnect");await owner.RefreshData();Close();owner.ShowLogin();}));Tab("账户与设备",account);
        var auth=Page("授权与恢复","扫描新设备的二维码，或输入 12 位授权码。");auth.Children.Add(Button("授权与恢复",()=>owner.ShowAuthorization()));Tab("授权与恢复",auth);
        var membership=Page("会员","会员权益在所有平台使用同一个账户同步。");var entitlement=Palette.Text(L10n.Text("点击刷新查看当前会员状态。"));membership.Children.Add(entitlement);membership.Children.Add(Button("刷新会员状态",async()=>{var data=await owner.CallCore("refreshMembership") as JsonObject;var access=data?["entitlement"] as JsonObject??new();entitlement.Text=string.Join("\n",new[]{L10n.Text("套餐")+": "+(access["plan"]?.ToString()??"—"),L10n.Text("状态")+": "+L10n.Text(access["active"]?.GetValue<bool>()==true?"有效":"未激活"),L10n.Text("到期时间")+": "+(access["until"]?.ToString()??"—"),L10n.Text("来源")+": "+(access["source"]?.ToString()??"—")});}));membership.Children.Add(Button("购买 / 管理会员",async()=>{await Windows.System.Launcher.LaunchUriAsync(new Uri("https://cliper.dev"));}));Tab("会员",membership);
        var privacy=Page("隐私与存储","内容在本机加密，云端同步加密数据。恢复文件和密钥请妥善保管。");privacy.Children.Add(Button("清理未使用的附件",async()=>{if(await owner.Dialog(L10n.Text("清理未使用的附件"),Palette.Text(L10n.Text("仅清理没有记录引用的本机附件。")),L10n.Text("清理"))==ContentDialogResult.Primary){var result=await owner.CallCore("clearUnused");notice.Text=result?.ToJsonString()??"";}}));privacy.Children.Add(Button("锁定资料库",async()=>{await owner.LockVault();Close();owner.ShowLogin();}));Tab("隐私与存储",privacy);
        var about=Page("关于 Clipper","加密剪贴板 · 云端多设备同步");about.Children.Add(Palette.Text("Clipper",32,true));about.Children.Add(Palette.Text(typeof(App).Assembly.GetName().Version?.ToString()??""));about.Children.Add(Button("官方网站",async()=>{await Windows.System.Launcher.LaunchUriAsync(new Uri("https://cliper.dev"));}));about.Children.Add(Button("反馈",async()=>{await Windows.System.Launcher.LaunchUriAsync(new Uri("https://cliper.dev/contact"));}));about.Children.Add(Button("退出 Clipper",()=>{owner.Shell.Quit();return Task.CompletedTask;}));Tab("关于",about);
    }
}
